    }

    public static Rig rig(GameTestHelper h, int planters) {
        BlockPos core = new BlockPos(1, 1, 1);
        BlockPos power = new BlockPos(2, 1, 1);
        BlockPos export = new BlockPos(3, 1, 1);
        h.setBlock(core, MPBlocks.CORE.get());
